import { useState } from 'react';
import type { FormEvent } from 'react';
import { JxStepper, JxInputField, JxButton } from '@jinx-ui/react';

interface RegistrationFormProps {
  onSubmit: (data: {
    fullName: string;
    email: string;
    phone: string;
    street: string;
    city: string;
    postalCode: string;
  }) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [street, setStreet] = useState('');
  const [city, setCity] = useState('');
  const [postalCode, setPostalCode] = useState('');

  const isLastStep = step === steps.length - 1;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isLastStep) {
      setStep((s) => Math.min(s + 1, steps.length - 1));
      return;
    }
    onSubmit({ fullName, email, phone, street, city, postalCode });
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '24px',
        maxWidth: '420px',
        padding: '24px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow)',
      }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <JxInputField
            label="Имя и фамилия"
            required
            value={fullName}
            onChange={(e) => setFullName(e.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
          <JxInputField
            label="Телефон"
            prefix="+7"
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <JxInputField
            label="Улица и дом"
            required
            value={street}
            onChange={(e) => setStreet(e.target.value)}
          />
          <JxInputField
            label="Город"
            required
            value={city}
            onChange={(e) => setCity(e.target.value)}
          />
          <JxInputField
            label="Почтовый индекс"
            value={postalCode}
            onChange={(e) => setPostalCode(e.target.value)}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', color: 'var(--jx-text-2)' }}>
          <div><strong style={{ color: 'var(--jx-text)' }}>Имя и фамилия:</strong> {fullName || '—'}</div>
          <div><strong style={{ color: 'var(--jx-text)' }}>Email:</strong> {email || '—'}</div>
          <div><strong style={{ color: 'var(--jx-text)' }}>Телефон:</strong> {phone ? `+7${phone}` : '—'}</div>
          <div><strong style={{ color: 'var(--jx-text)' }}>Адрес:</strong> {street || '—'}, {city || '—'} {postalCode}</div>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '12px' }}>
        <JxButton
          type="button"
          variant="ghost"
          disabled={step === 0}
          onClick={() => setStep((s) => Math.max(s - 1, 0))}
        >
          Назад
        </JxButton>
        {isLastStep ? (
          <JxButton type="submit" variant="primary">
            Отправить
          </JxButton>
        ) : (
          <JxButton type="submit" variant="primary">
            Дальше
          </JxButton>
        )}
      </div>
    </form>
  );
}

